const L = params.length;
const s = L / 14;
const W = 3.7 * s;
const hullMat = { preset: 'wood', color: params.hullColor, roughness: 0.82, flatShading: true };
const darkWood = { preset: 'wood', color: '#3a2116', roughness: 0.88 };
const trimMat = { preset: 'wood', color: '#b17a3e', roughness: 0.72 };
const sailMat = { preset: 'fabric', color: params.sailColor, roughness: 0.96 };
const ropeMat = { preset: 'fabric', color: '#4a3825', roughness: 1 };
const metalMat = { preset: 'metal', color: '#25282a', metalness: 0.65, roughness: 0.48 };
const glassMat = { preset: 'glass', color: '#7ca6b7', opacity: 0.72, roughness: 0.18 };
const hullShape = [[-6.3*s,1.75*s],[-6.75*s,1.25*s],[-5.8*s,0.2*s],[-3.7*s,-0.8*s],[0,-1.22*s],[3.8*s,-0.78*s],[6.05*s,0.15*s],[6.65*s,1.55*s],[5.85*s,1.78*s],[-5.6*s,1.78*s]];
api.add(api.extrude(hullShape, W * 0.72), hullMat);
const lower = api.extrude([[-5.75*s,0.65*s],[-4.2*s,-0.55*s],[0,-1.34*s],[4.25*s,-0.55*s],[5.8*s,0.65*s]], W * 0.46);
lower.vertexColor((x,y,z) => api.mix(params.hullColor, '#24130d', 0.48));
api.add(lower, { preset: 'wood', roughness: 0.9, flatShading: true });
api.add(api.box(11.8*s,0.18*s,W*0.82).translate(-0.1*s,1.82*s,0), trimMat);
api.add(api.box(4.0*s,0.62*s,W*0.76).translate(-4.15*s,2.18*s,0), hullMat);
api.add(api.box(3.2*s,0.18*s,W*0.84).translate(-4.45*s,2.56*s,0), trimMat);
api.add(api.box(2.35*s,0.52*s,W*0.72).translate(-4.75*s,2.9*s,0), hullMat);
api.add(api.box(2.65*s,0.16*s,W*0.8).translate(-4.72*s,3.2*s,0), trimMat);
api.add(api.box(2.0*s,0.42*s,W*0.66).translate(4.65*s,2.1*s,0), hullMat);
api.add(api.box(2.35*s,0.16*s,W*0.78).translate(4.7*s,2.36*s,0), trimMat);
for (let side = -1; side <= 1; side += 2) {
  const z = side * W * 0.405;
  api.add(api.box(11.4*s,0.12*s,0.12*s).translate(-0.1*s,2.18*s,z), trimMat);
  for (let i=0;i<13;i++) api.add(api.box(0.09*s,0.55*s,0.09*s).translate((-5.45+i*0.9)*s,2.42*s,z), darkWood);
  api.add(api.box(11.5*s,0.09*s,0.09*s).translate(-0.05*s,2.68*s,z), darkWood);
  for (let i=0;i<7;i++) {
    const x=(-3.6+i*1.18)*s;
    api.add(api.box(0.55*s,0.42*s,0.08*s).translate(x,1.05*s,side*W*0.371), metalMat);
    api.add(api.cylinder(0.11*s,0.11*s,0.58*s,8).rotate(90,0,0).translate(x,1.05*s,side*(W*0.49)), metalMat);
  }
}
for (let side=-1;side<=1;side+=2) {
  for (let i=0;i<4;i++) api.add(api.box(0.42*s,0.52*s,0.06*s).translate((-5.25+i*0.62)*s,2.84*s,side*W*0.345), glassMat);
}
const mastXs=[-1.8*s,2.25*s];
const mastHs=[9.7*s,8.25*s];
for(let m=0;m<2;m++) {
  const x=mastXs[m], mh=mastHs[m];
  api.add(api.cylinder(0.13*s,0.2*s,mh,10).translate(x,2.0*s+mh/2,0), darkWood);
  const levels=m===0?[6.0,8.0,9.55]:[5.5,7.25,8.65];
  const widths=m===0?[4.6,3.65,2.6]:[4.1,3.2,2.2];
  for(let j=0;j<3;j++) {
    const y=levels[j]*s;
    const yw=widths[j]*s;
    api.add(api.cylinder(0.075*s,0.075*s,yw,8).rotate(0,0,90).translate(x,y,0),darkWood);
    const sh=(j===0?1.65:j===1?1.38:1.08)*s;
    const sail=api.extrude([[-yw*0.46,0],[yw*0.46,0],[yw*0.39,-sh],[-yw*0.39,-sh]],0.055*s).translate(x,y-0.08*s,0);
    sail.vertexColor((vx,vy,vz)=>api.mix(params.sailColor,'#b9a985',Math.min(0.24,Math.abs(vx-x)/(yw*2))));
    api.add(sail,sailMat);
    api.add(api.cylinder(0.035*s,0.035*s,yw*0.78,6).rotate(0,0,90).translate(x,y-sh,0),ropeMat);
  }
  api.add(api.tube([[x,2.3*s,0],[x,mh+2.0*s,0]],0.025*s,5),ropeMat);
  api.add(api.sphere(0.19*s,1).translate(x,mh+2.05*s,0),trimMat);
}
const bowTip=[8.5*s,4.0*s,0];
api.add(api.tube([[5.3*s,2.0*s,0],bowTip],0.13*s,8),darkWood);
api.add(api.tube([[-5.7*s,2.55*s,0],[-1.8*s,11.7*s,0]],0.025*s,5),ropeMat);
api.add(api.tube([[5.5*s,2.45*s,0],[2.25*s,10.25*s,0]],0.025*s,5),ropeMat);
api.add(api.tube([[-1.8*s,11.7*s,0],bowTip],0.022*s,5),ropeMat);
for(let side=-1;side<=1;side+=2) {
  api.add(api.tube([[-5.2*s,2.55*s,side*W*0.38],[-1.8*s,11.7*s,0],[0.2*s,2.3*s,side*W*0.39]],0.024*s,5),ropeMat);
  api.add(api.tube([[0.1*s,2.3*s,side*W*0.39],[2.25*s,10.25*s,0],[5.5*s,2.45*s,side*W*0.35]],0.024*s,5),ropeMat);
}
api.add(api.torus(0.46*s,0.07*s).rotate(90,0,0).translate(-4.0*s,2.92*s,0),darkWood);
for(let i=0;i<8;i++) {
  const a=i*Math.PI/4;
  api.add(api.box(0.06*s,1.18*s,0.06*s).rotate(0,0,i*45).translate(-4.0*s,2.92*s,0),darkWood);
}
api.add(api.cylinder(0.07*s,0.07*s,0.65*s,8).rotate(90,0,0).translate(-4.0*s,2.92*s,0),metalMat);
api.collider({kind:'hull',points:[-6.3*s,1.75*s,-W*.36,-5.8*s,.2*s,-W*.25,0,-1.22*s,-W*.18,6.4*s,1.5*s,-W*.3,-6.3*s,1.75*s,W*.36,-5.8*s,.2*s,W*.25,0,-1.22*s,W*.18,6.4*s,1.5*s,W*.3],offset:[0,0,0]});
api.collider({kind:'box',halfExtents:[5.9*s,.42*s,W*.41],offset:[-.1*s,2.05*s,0]});
api.collider({kind:'capsule',radius:.2*s,halfHeight:4.8*s,offset:[-1.8*s,6.8*s,0]});
api.collider({kind:'capsule',radius:.2*s,halfHeight:4.1*s,offset:[2.25*s,6.2*s,0]});
return api.build();
